css:
.banner {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  height: 240px;
  margin: 16px;
  padding: 20px;
  border-radius: 12px;
  color: #ffffff;
  font-family: system-ui, sans-serif;
  background-image:
    linear-gradient(transparent 40%, rgb(0 0 0 / 0.7)),
    radial-gradient(circle, #fde68a, transparent 70%),
    linear-gradient(135deg, #7c3aed, #ea580c);
  background-size: 100% 100%, 260px 260px, 100% 100%;
  background-position: center, top right, center;
  background-repeat: no-repeat, no-repeat, no-repeat;
}

.banner-title {
  margin: 0 0 4px;
}

.banner-text {
  margin: 0;
}
